#include <unordered_map>
#include <vector>
#include <algorithm>

using namespace std;

int main(){
    int n, a, b;
    string number;
    unordered_map<string, int> info;
    vector<string> seq;

    while(cin >> n && n){
        info.clear();
        seq.clear();
        while(n--){
            cin >> number >> a >> b;
            // Simplified check with insert
            auto result = info.insert({number, 0});
            if (result.second) seq.push_back(number); // Inserted new entry
            if (info[number] < 1000000) {
                info[number] = min(info[number] + a * b, 1000000); // Update in one go
            }
        }
        bool flag = true;
        for(const auto& num : seq){ // Use range-based for loop for clarity
            if(info[num] >= 1000000){
                flag = false;
                cout << num << endl;
            }
        }
        if(flag) cout << "NA" << endl;
    }
}

