void printResults(const vector<string>& seq, const unordered_map<string, int>& info) {
    bool flag = true;
    for(const auto& elem : seq) {
        if(info.at(elem) >= 1000000) {
            flag = false;
            cout << elem << endl;
        }
    }
    if(flag) cout << "NA" << endl;
}

